import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from http.server import BaseHTTPRequestHandler
import json
import re
import ast

SECRET_KEY = os.environ.get('APP_SECRET', os.urandom(32).hex())
BASE_DIR = '/srv/data/public'
BLOCKED_SEGMENTS = {'..', '.git', '.env', 'private', 'secret', 'admin'}

def _constant_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def _verify_request_mac(path, timestamp, provided_mac):
    """Verify HMAC of request to prevent tampering."""
    msg = f"{path}:{timestamp}"
    expected = hmac.new(SECRET_KEY.encode(), msg.encode(), hashlib.sha256).hexdigest()
    return _constant_compare(expected, provided_mac)

def _sanitize_path_segment(segment):
    """Check a single path segment for dangerous patterns."""
    # Block null bytes
    if '\x00' in segment:
        return False
    # Block directory traversal and sensitive names
    if segment.lower() in BLOCKED_SEGMENTS:
        return False
    # Block segments starting with dot (hidden files)
    if segment.startswith('.'):
        return False
    return True

def _validate_path(path_str):
    """Validate the path string against security rules.
    Returns (is_valid, reason) tuple."""
    # Must start with /
    if not path_str.startswith('/'):
        return False, "Path must be absolute"
    # Check for null bytes in entire path
    if '\x00' in path_str:
        return False, "Null bytes not allowed"
    # Parse into segments
    segments = [s for s in path_str.split('/') if s]
    for seg in segments:
        if not _sanitize_path_segment(seg):
            return False, f"Blocked segment: {seg}"
    # Check resolved path doesn't escape
    resolved = PurePosixPath(path_str)
    parts = resolved.parts[1:]  # skip root '/'
    for part in parts:
        if not _sanitize_path_segment(part):
            return False, f"Blocked resolved segment: {part}"
    return True, None

def _normalize_unicode(text):
    """Normalize unicode to canonical form for consistent handling.
    Uses NFKC normalization as recommended for security contexts."""
    return unicodedata.normalize('NFKC', text)

def resolve_file_path(user_path):
    """Resolve a user-provided path to a filesystem path.

    Security: validates path segments, blocks traversal,
    normalizes unicode for consistent handling.
    """
    # Step 1: Validate the raw input path
    is_valid, reason = _validate_path(user_path)
    if not is_valid:
        return None, reason

    # Step 2: Normalize unicode AFTER validation
    normalized = _normalize_unicode(user_path)

    # Step 3: Construct final path using normalized form
    final_path = os.path.join(BASE_DIR, normalized.lstrip('/'))

    # Step 4: Verify final path is under BASE_DIR
    real_base = os.path.realpath(BASE_DIR)
    real_final = os.path.realpath(final_path)
    if not real_final.startswith(real_base + os.sep) and real_final != real_base:
        return None, "Path escapes base directory"

    return real_final, None

def handle_read_request(request_path, auth_header=None):
    """Handle a file read request with path validation."""
    if not request_path:
        return {'status': 400, 'error': 'No path provided'}

    resolved, error = resolve_file_path(request_path)
    if error:
        return {'status': 403, 'error': error}

    if not os.path.exists(resolved):
        return {'status': 404, 'error': 'Not found'}

    if os.path.isdir(resolved):
        # List directory contents (non-hidden only)
        entries = [e for e in os.listdir(resolved) if not e.startswith('.')]
        return {'status': 200, 'type': 'directory', 'entries': entries}

    try:
        with open(resolved, 'r', encoding='utf-8') as f:
            content = f.read(1024 * 1024)  # 1MB limit
        return {'status': 200, 'type': 'file', 'content': content}
    except (IOError, UnicodeDecodeError) as e:
        return {'status': 500, 'error': 'Read error'}

def handle_search_request(query_params):
    """Handle a search request with safe expression evaluation."""
    if 'filter' not in query_params:
        return {'status': 400, 'error': 'No filter provided'}

    # Use ast.literal_eval for safe parsing of filter expressions
    try:
        filter_spec = ast.literal_eval(query_params['filter'])
    except (ValueError, SyntaxError):
        return {'status': 400, 'error': 'Invalid filter syntax'}

    if not isinstance(filter_spec, dict):
        return {'status': 400, 'error': 'Filter must be a dict'}

    # Apply filter to find matching files
    results = []
    allowed_keys = {'name', 'ext', 'min_size', 'max_size'}
    if not set(filter_spec.keys()).issubset(allowed_keys):
        return {'status': 400, 'error': 'Invalid filter keys'}

    return {'status': 200, 'results': results}
